<script lang="ts">
  import {getContext as privacyContext} from 'svelte';
  import {concealed,PRIVACY_CONTEXT,type PrivacyState} from '$lib/privacy';
  const privacy=privacyContext<PrivacyState>(PRIVACY_CONTEXT);
  import { getContext, onMount } from 'svelte';
  import { AUTH_UI_CONTEXT, type AuthUiState } from '$lib/i18n/auth';
  import { assistantText } from '$lib/i18n/assistant';
  import { Button } from '$lib/components/ui/button';
  import * as Card from '$lib/components/ui/card';
  import * as Field from '$lib/components/ui/field';
  import { Input } from '$lib/components/ui/input';
  import type { ECharts } from 'echarts/core';
  type Workspace={selectedId:string;ready:boolean};
  type AssistantSettings={localForecastEnabled:boolean;suggestionsEnabled:boolean;categorizationEnabled:boolean;externalAiEnabled:boolean;externalAiAvailable:boolean;sourcePermissions:Record<string,boolean>;tone:'playful'|'balanced'|'professional';defaultHorizonDays:number;safetyBuffer:string;consentVersion:number;version:number;configured?:boolean};
  type AccountPreference={id:string;name:string;kind:string;currency:string;included:boolean;allowExternalAi:boolean;lowBalanceThreshold:string;protectedAmount:string};
  type LearnedRule={id:string;type:string;merchant:string;categoryName:string;origin:string;supportCount:number;acceptedCount:number;enabled:boolean;version:number};
  type HistoryTransaction={id:string;date:string;type:'income'|'expense';merchant:string|null;categoryName:string|null;amount:string;version:number;excluded:boolean;overrideVersion:number};
  type Forecast={asOfDate:string;currency:string;horizonDays:number;coverage:string;safeToSpend:string|null;safeToSpendReason:string;protectedAmount:string;minimumBalance:string;firstShortfallDate:string|null;firstLowBalanceDate:string|null;qualityFlags:string[];history:{accountId:string;accountName:string;from:string;through:string;eligibleDays:number;expenseTotal:string;incomeTotal:string;dailyExpenseAverage:string|null;dailyIncomeAverage:string|null}[];points:{date:string;openingBalance:string;inflows:string;outflows:string;closingBalance:string;minimumBalance:string;headroom:string;scenario:'base'|'conservative'}[]};
  const workspace=getContext<Workspace>('capybudget-workspaces'),ui=getContext<AuthUiState>(AUTH_UI_CONTEXT);
  const t=(key:Parameters<typeof assistantText>[1])=>assistantText(ui.locale,key);
  let forecastEvents:{id:string;date:string;kind:string;description:string;amount:string;currency:string;accountId:string|null}[]=$state([]);
  let uncertainReceivables:{invoiceId:string;invoiceNumber:string;dueDate:string;outstanding:string;currency:string;accountId:string|null}[]=$state([]);
  let historyTransactions:HistoryTransaction[]=$state([]),historyBusy=$state('');
  let settings:AssistantSettings|null=$state(null),accountSettings:AccountPreference[]=$state([]),rules:LearnedRule[]=$state([]),forecast:Forecast|null=$state(null),suggestions:any[]=$state([]),proposals:Record<string,any>=$state({}),proposalKeys:Record<string,string>=$state({}),actionBusy=$state(''),loading=$state(false),saving=$state(false),savingChannels=$state(false),deletingData=$state(false),emailAlerts=$state(false),pushAlerts=$state(false),error=$state(''),notice=$state(''),horizon=$state(30),scopeAccount=$state(''),buffer=$state('0'),tone=$state<'playful'|'balanced'|'professional'>('balanced'),localForecast=$state(true),suggestionsEnabled=$state(true),categorization=$state(true),permissions:Record<string,boolean>=$state({history:true,recurring:true,bills:true,invoices:true,budgets:false,goals:false,merchant:true,notes:false});
  let chartHost:HTMLDivElement|undefined=$state(),chart:ECharts|null=$state(null),forecastSequence=0,settingsSequence=0,prefersReducedMotion=false,displayScenario=$state<'both'|'base'|'conservative'>('both');
  const labels=$derived({history:t('history'),recurring:t('recurring'),bills:t('bills'),invoices:t('invoices'),merchant:t('merchant'),notes:t('notes')});
  onMount(()=>{let disposed=false;let observer:ResizeObserver|undefined;const motion=window.matchMedia('(prefers-reduced-motion: reduce)');const updateMotion=()=>{prefersReducedMotion=motion.matches;drawChart();};updateMotion();motion.addEventListener('change',updateMotion);void Promise.all([import('echarts/core'),import('echarts/charts'),import('echarts/components'),import('echarts/renderers')]).then(([echarts,charts,components,renderers])=>{if(disposed||!chartHost)return;echarts.use([charts.LineChart,components.GridComponent,components.TooltipComponent,renderers.CanvasRenderer]);chart=echarts.init(chartHost);observer=new ResizeObserver(()=>chart?.resize());observer.observe(chartHost);drawChart();});return()=>{disposed=true;motion.removeEventListener('change',updateMotion);observer?.disconnect();chart?.dispose();chart=null;};});
  $effect(()=>{void (workspace as {revision?:number}).revision;privacy.hidden;forecast;forecastEvents;ui.locale;displayScenario;drawChart();});
  $effect(()=>{void (workspace as {revision?:number}).revision;if(workspace.ready&&workspace.selectedId)void load();});
  async function load(){const id=workspace.selectedId;if(!id)return;const sequence=++settingsSequence;loading=true;error='';try{const [response,ruleResponse,notificationResponse]=await Promise.all([fetch(`/api/workspaces/${id}/assistant/settings`),fetch(`/api/workspaces/${id}/assistant/category-rules`),fetch(`/api/workspaces/${id}/notification-preferences`)]);if(sequence!==settingsSequence||id!==workspace.selectedId)return;if(!response.ok)throw new Error(t('loadSettingsError'));const body=await response.json();settings={...body.settings,configured:body.configured};accountSettings=body.accounts;rules=(await ruleResponse.json()).items??[];const notificationBody=await notificationResponse.json();if(notificationResponse.ok){emailAlerts=notificationBody.emailAssistantAlerts??false;pushAlerts=notificationBody.pushAssistantAlerts??false;}localForecast=body.settings.localForecastEnabled;suggestionsEnabled=body.settings.suggestionsEnabled;categorization=body.settings.categorizationEnabled;tone=body.settings.tone;permissions={...body.settings.sourcePermissions};horizon=body.settings.defaultHorizonDays;scopeAccount='';buffer=body.settings.safetyBuffer;if(body.configured)await loadForecast();else{forecast=null;forecastEvents=[];uncertainReceivables=[];suggestions=[];proposals={};} }catch{if(sequence===settingsSequence&&id===workspace.selectedId)error=t('loadSettingsError');}finally{if(sequence===settingsSequence)loading=false;}}
  async function loadForecast(){
    if(!workspace.selectedId)return;
    const id=workspace.selectedId,sequence=++forecastSequence;
    forecast=null;forecastEvents=[];historyTransactions=[];uncertainReceivables=[];suggestions=[];error='';
    try{
      for(let refreshAttempt=0;refreshAttempt<2;refreshAttempt++){
        const queued=await fetch('/api/workspaces/'+id+'/assistant/forecast/refresh',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({horizon,accountId:scopeAccount||null,idempotencyKey:crypto.randomUUID()})});
        if(sequence!==forecastSequence||id!==workspace.selectedId)return;
        if(!queued.ok)throw new Error(t('forecastError'));
        const {runId}=await queued.json();let completed:any=null;
        for(let poll=0;poll<100;poll++){
          const response=await fetch('/api/workspaces/'+id+'/assistant/forecast/'+runId);
          if(sequence!==forecastSequence||id!==workspace.selectedId)return;
          if(response.status===404){await new Promise(resolve=>setTimeout(resolve,250));continue;}
          if(!response.ok)throw new Error(t('forecastError'));
          const body=await response.json();
          if(body.run?.status==='ready'){completed=body;break;}
          if(body.run?.status==='failed'||body.run?.status==='superseded')break;
          await new Promise(resolve=>setTimeout(resolve,250));
        }
        if(completed){
          const suggestionResponse=await fetch('/api/workspaces/'+id+'/assistant/suggestions');
          if(sequence!==forecastSequence||id!==workspace.selectedId)return;
          const suggestionBody=suggestionResponse.ok?await suggestionResponse.json():{items:[]};
          const savedPoints=completed.points??[],displayPoints=scopeAccount?savedPoints.filter((point:any)=>point.accountId===scopeAccount):savedPoints.filter((point:any)=>point.accountId===null);
          forecast={...completed.forecast,points:displayPoints};forecastEvents=completed.events??[];historyTransactions=completed.historyTransactions??[];uncertainReceivables=completed.uncertainReceivables??[];suggestions=suggestionBody.items??[];
          proposals=Object.fromEntries(suggestions.filter((row:any)=>row.proposalId).map((row:any)=>[row.id,{id:row.proposalId,payload:row.proposalPayload,payloadHash:row.proposalPayloadHash,expiresAt:row.proposalExpiresAt}]));
          return;
        }
      }
      throw new Error(t('forecastError'));
    }catch{if(sequence===forecastSequence&&id===workspace.selectedId)error=t('forecastError');}
  }
  async function toggleHistoryOverride(item:HistoryTransaction){if(!workspace.selectedId||historyBusy)return;historyBusy=item.id;error='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/history-overrides/${item.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.overrideVersion,excludeFromBaseline:!item.excluded,reason:item.excluded?undefined:'Marked as an unusual one-off expense or income.'})});if(!response.ok)throw new Error();notice=item.excluded?t('historyIncludedNotice'):t('historyExcludedNotice');await loadForecast();}catch{error=t('historyOverrideError');}finally{historyBusy='';}}
  async function save(){if(!settings||saving)return;saving=true;error='';notice='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/settings`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({version:settings.version,sourcePermissions:permissions,defaultHorizonDays:horizon,safetyBuffer:buffer,tone,localForecastEnabled:localForecast,suggestionsEnabled,categorizationEnabled:categorization,accounts:accountSettings.map(({id,included,allowExternalAi,lowBalanceThreshold,protectedAmount})=>({id,included,allowExternalAi,lowBalanceThreshold,protectedAmount}))})});if(!response.ok)throw new Error(t('saveSettingsError'));const body=await response.json();settings={...settings,version:body.version,consentVersion:body.consentVersion};scopeAccount='';notice=t('settingsSaved');await loadForecast();}catch{error=t('saveSettingsError');}finally{saving=false;}}
  async function saveChannels(){if(savingChannels)return;savingChannels=true;error='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/notification-preferences`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({emailAssistantAlerts:emailAlerts,pushAssistantAlerts:pushAlerts})});if(!response.ok)throw new Error(t('saveAlertPreferencesError'));const body=await response.json();emailAlerts=body.emailAssistantAlerts;pushAlerts=body.pushAssistantAlerts;notice=t('channelsSaved');}catch{error=t('saveAlertPreferencesError');}finally{savingChannels=false;}}
  async function setRuleEnabled(rule:LearnedRule){const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/category-rules/${rule.id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({version:rule.version,enabled:!rule.enabled})});if(!response.ok){error=t('updateRuleError');return;}const body=await response.json();rules=rules.map((item)=>item.id===rule.id?{...item,...body}:item);}
  async function resetLearnedRules(){const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/category-rules/reset`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({includeExplicit:false})});if(!response.ok){error=t('resetRulesError');return;}rules=rules.filter((rule)=>rule.origin!=='learned');notice=t('resetDone');}
  async function exportAssistantData(){error='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/export`);if(!response.ok)throw new Error();const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`capybudget-assistant-${workspace.selectedId}.json`;link.click();URL.revokeObjectURL(url);notice=t('assistantDataExported');}catch{error=t('assistantDataExportError');}}
  async function deleteAssistantData(){if(!settings||deletingData||!window.confirm(t('deleteAssistantConfirm')))return;deletingData=true;error='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/data`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({confirmation:'DELETE_ASSISTANT_DATA',consentVersion:settings.consentVersion})});if(!response.ok)throw new Error();forecast=null;forecastEvents=[];uncertainReceivables=[];suggestions=[];rules=[];proposals={};notice=t('assistantDataDeleted');await load();}catch{error=t('assistantDataDeleteError');}finally{deletingData=false;}}
  async function suggestionFeedback(item:any,action:'helpful'|'not_helpful'|'dismiss'|'snooze'){const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/suggestions/${item.id}/feedback`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({version:item.version,action,snoozeDays:7})});if(!response.ok){error=t('feedbackError');return;}const body=await response.json();Object.assign(item,body);if(action==='dismiss'||action==='snooze')suggestions=suggestions.filter((row)=>row.id!==item.id);}
  async function createProposal(item:any,actionType='send_invoice_reminder'){actionBusy=item.id;error='';const idempotencyKey=proposalKeys[item.id]??crypto.randomUUID();proposalKeys={...proposalKeys,[item.id]:idempotencyKey};try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/suggestions/${item.id}/proposals`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({actionType,version:item.version,idempotencyKey})});if(!response.ok)throw new Error(t('prepareActionError'));const body=await response.json();proposals={...proposals,[item.id]:body.proposal};item.version+=1;item.state='reviewing';}catch{error=t('prepareActionError');}finally{actionBusy='';}}
  async function confirmProposal(item:any){const proposal=proposals[item.id];if(!proposal)return;actionBusy=item.id;error='';try{const response=await fetch(`/api/workspaces/${workspace.selectedId}/assistant/proposals/${proposal.id}/confirm`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({payloadHash:proposal.payloadHash})});if(!response.ok)throw new Error(t('confirmActionError'));notice=item.kind==='savings'?t('savedToGoal'):item.kind==='payment_delay'?t('dateUpdatedNotice'):t('sentNotice');item.state='completed';delete proposals[item.id];delete proposalKeys[item.id];if(item.kind==='payment_delay')await loadForecast();}catch{error=t('confirmActionError');}finally{actionBusy='';}}
  function money(value:string|null){if(privacy.hidden)return '••••••';return value===null?t('unavailable'):`${forecast?.currency??''} ${value}`;}
  function monthDay(value:string){const raw=String(value??''),date=new Date(/^\d{4}-\d{2}-\d{2}$/.test(raw)?`${raw}T00:00:00Z`:raw);if(Number.isNaN(date.valueOf()))return raw.slice(0,10);return new Intl.DateTimeFormat(ui.locale==='id'?'id-ID':'en',{month:'short',day:'numeric',timeZone:'UTC'}).format(date);}
  function actionLabel(suggestion:any){if(suggestion.kind==='shortfall')return t('shortfall');if(suggestion.kind==='low_balance')return t('lowBalance');if(suggestion.kind==='savings')return t('savingsOpportunity');if(suggestion.kind==='payment_delay')return suggestion.facts?.needsTermsConfirmation?t('checkTerms'):t('paymentDelay');return t('invoiceFollowup');}
  function qualityLabel(flag:string){if(flag.startsWith('insufficient_history:'))return `${t('insufficientHistoryFlag')}: ${accountSettings.find((account)=>account.id===flag.split(':')[1])?.name??''}`;const labels:Record<string,Parameters<typeof assistantText>[1]>={history_source_excluded:'historyExcludedFlag',recurring_source_excluded:'recurringExcludedFlag',bills_source_excluded:'billsExcludedFlag',invoices_source_excluded:'invoicesExcludedFlag',legacy_paid_bill_without_transaction:'legacyBillGapFlag',unassigned_bill_account:'unassignedBillFlag',unassigned_invoice_account:'unassignedInvoiceFlag',unassigned_forecast_account:'unassignedForecastFlag',unresolved_source_overlap:'sourceOverlapFlag',other_currency_accounts_excluded:'otherCurrencyFlag',bill_currency_mismatch:'billCurrencyFlag',invoice_currency_mismatch:'invoiceCurrencyFlag',transfer_scope_boundary:'transferScopeFlag'};return labels[flag]?t(labels[flag]):flag;}
  function escapeTooltip(value:string){return value.replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[character]??character));}
  function chartSummary(){return t('chartSummary').replace('{days}',String(forecast?.horizonDays??horizon)).replace('{minimum}',money(forecast?.minimumBalance??null)).replace('{safe}',money(forecast?.safeToSpend??null));}
  function drawChart(){
    if(privacy.hidden){chart?.clear();return;}
    if(!chart||!forecast)return;
    const activeForecast=forecast;
    const base=forecast.points.filter((point)=>point.scenario==='base'),conservative=forecast.points.filter((point)=>point.scenario==='conservative');
    const points=displayScenario==='conservative'?conservative:base;
    const eventsByDate=new Map<string,typeof forecastEvents>();
    for(const event of forecastEvents){const day=eventsByDate.get(event.date)??[];day.push(event);eventsByDate.set(event.date,day);}
    const series:any[]=[];
    const baseSeries:any={name:t('expected'),type:'line',showSymbol:false,smooth:.2,data:base.map((point)=>Number(point.closingBalance)),lineStyle:{width:3,color:'#5caa7b'},areaStyle:{opacity:.08,color:'#5caa7b'}};
    const conservativeSeries:any={name:t('conservative'),type:'line',showSymbol:false,smooth:.2,data:conservative.map((point)=>Number(point.closingBalance)),lineStyle:{width:2,type:'dashed',color:'#e6a06d'}};
    const markEvents=(target:any)=>{target.markPoint={symbol:'circle',symbolSize:12,label:{show:false},itemStyle:{color:'#47785a',borderColor:'#ffffff',borderWidth:2},data:[...eventsByDate].flatMap(([date,events])=>{const point=points.find((row)=>row.date===date);return point?[{name:`${events.length} ${t('sourceEvents')}`,coord:[date,Number(point.closingBalance)],eventCount:events.length}]:[];})};};
    markEvents(displayScenario==='conservative'?conservativeSeries:baseSeries);
    if(displayScenario!=='conservative')series.push(baseSeries);
    if(displayScenario!=='base')series.push(conservativeSeries);
    chart.setOption({animationDuration:prefersReducedMotion?0:350,grid:{left:58,right:18,top:18,bottom:38},tooltip:{trigger:'axis',renderMode:'html',formatter:(params:any[])=>{const date=String(params?.[0]?.axisValue??'');const basePoint=base.find((point)=>point.date===date),conservativePoint=conservative.find((point)=>point.date===date);if(!basePoint||!conservativePoint)return '';const details:string[]=[`<strong>${escapeTooltip(date)}</strong>`];if(displayScenario!=='conservative')details.push(`${escapeTooltip(t('expected'))}: ${escapeTooltip(activeForecast.currency)} ${escapeTooltip(basePoint.closingBalance)}`);if(displayScenario!=='base')details.push(`${escapeTooltip(t('conservative'))}: ${escapeTooltip(activeForecast.currency)} ${escapeTooltip(conservativePoint.closingBalance)}`);const events=eventsByDate.get(date)??[];if(events.length)details.push(`<strong>${escapeTooltip(t('sourceEvents'))}</strong>`,...events.slice(0,8).map((event)=>`${escapeTooltip(event.description)}: ${escapeTooltip(event.currency)} ${escapeTooltip(event.amount)}`));return details.join('<br/>');}},xAxis:{type:'category',boundaryGap:false,data:base.map((point)=>point.date),axisLabel:{hideOverlap:true}},yAxis:{type:'value',scale:true,axisLabel:{formatter:(value:number)=>new Intl.NumberFormat(ui.locale==='id'?'id-ID':'en',{notation:'compact',maximumFractionDigits:1}).format(value)}},series});
  }
</script>
<svelte:head><title>CapyBudget · {t('title')}</title><meta name="description" content={t('intro')} /></svelte:head>
<div class="page-head"><div><p class="eyebrow">{t('eyebrow')}</p><h1>{t('title')}</h1><p>{t('intro')}</p></div><div class="head-controls"><label class="horizon">{t('forecast')}<select bind:value={horizon} onchange={()=>loadForecast()}><option value={30}>30 {t('days')}</option><option value={60}>60 {t('days')}</option><option value={90}>90 {t('days')}</option></select></label><label class="horizon">{t('account')}<select bind:value={scopeAccount} onchange={()=>loadForecast()}><option value="">{t('allAccounts')}</option>{#each accountSettings.filter((account)=>account.included&&account.currency===forecast?.currency) as account (account.id)}<option value={account.id}>{account.name}</option>{/each}</select></label><Button variant="outline" href="/settings/assistant">{t('privacy')}</Button></div></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
{#if !workspace.ready||loading}<p role="status">{t('loading')}</p>{:else if forecast}
  <div class="stats">
    <Card.Root><Card.Header><Card.Description>{t('safeToSpend')}</Card.Description><Card.Title class="money">{money(forecast.safeToSpend)}</Card.Title><Card.Description>{forecast.safeToSpendReason==='incomplete_data'?t('excluded'):t('afterReserves')}</Card.Description></Card.Header></Card.Root>
    <Card.Root><Card.Header><Card.Description>{t('minimumBalance')}</Card.Description><Card.Title class="money">{money(forecast.minimumBalance)}</Card.Title><Card.Description>{forecast.firstShortfallDate?`${t('shortfallOn')} ${monthDay(forecast.firstShortfallDate)}`:forecast.firstLowBalanceDate?`${t('lowOn')} ${monthDay(forecast.firstLowBalanceDate)}`:t('periodOnly')}</Card.Description></Card.Header></Card.Root>
    <Card.Root><Card.Header><Card.Description>{t('protected')}</Card.Description><Card.Title class="money">{money(forecast.protectedAmount)}</Card.Title><Card.Description>{t('protectedHint')}</Card.Description></Card.Header></Card.Root>
  </div>
  <div class="columns">
    <Card.Root><Card.Header><Card.Title>{t('cashflow')}</Card.Title><Card.Description>{forecast.horizonDays} {t('days')} · {forecast.coverage==='complete_for_selected_sources'?t('complete'):t('incomplete')} · {t('asOf')} {monthDay(forecast.asOfDate)}</Card.Description><label class="scenario-select">{t('displayScenario')}<select bind:value={displayScenario}><option value="both">{t('bothScenarios')}</option><option value="base">{t('expected')}</option><option value="conservative">{t('conservative')}</option></select></label></Card.Header><Card.Content>
      {#if forecast.qualityFlags.length}<div class="flags" role="status"><strong>{t('limits')}</strong><p>{forecast.qualityFlags.map(qualityLabel).join(' · ')}</p><small>{t('limitHint')}</small></div>{/if}
      <div class="chart-wrap"><div bind:this={chartHost} class="cashflow-chart" role="img" aria-label={chartSummary()}></div><p class="chart-summary">{chartSummary()}</p><div class="chart-dates"><span>{forecast.points[0]?.date}</span><span>{forecast.points.at(-1)?.date}</span></div></div>
      <details class="data-table"><summary>{t('dailyValues')}</summary><div class="table-scroll"><table><caption>{t('tableCaption')} {forecast.currency}</caption><thead><tr><th scope="col">{t('date')}</th><th scope="col">{t('scenario')}</th><th scope="col">{t('opening')}</th><th scope="col">{t('inflows')}</th><th scope="col">{t('outflows')}</th><th scope="col">{t('closing')}</th><th scope="col">{t('minimum')}</th><th scope="col">{t('headroom')}</th></tr></thead><tbody>{#each forecast.points as point (`${point.date}:${point.scenario}`)}<tr><th scope="row">{point.date}</th><td>{point.scenario==='base'?t('expected'):t('conservative')}</td><td>{concealed(point.openingBalance,privacy.hidden)}</td><td>{concealed(point.inflows,privacy.hidden)}</td><td>{concealed(point.outflows,privacy.hidden)}</td><td>{concealed(point.closingBalance,privacy.hidden)}</td><td>{concealed(point.minimumBalance,privacy.hidden)}</td><td>{concealed(point.headroom,privacy.hidden)}</td></tr>{/each}</tbody></table></div></details>
      <section class="event-list" aria-labelledby="forecast-events-heading"><h3 id="forecast-events-heading">{t('sourceEvents')}</h3>{#if forecastEvents.length}<ul>{#each [...forecastEvents].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,100) as event (event.id)}<li><span><strong>{monthDay(event.date)}</strong><small>{event.description}{event.accountId?` · ${accountSettings.find((account)=>account.id===event.accountId)?.name??t('account')}`:''}</small></span><strong>{event.currency} {concealed(event.amount,privacy.hidden)}</strong></li>{/each}</ul>{:else}<p>{t('noEvents')}</p>{/if}</section>
      <section class="event-list" aria-labelledby="history-baseline-heading"><h3 id="history-baseline-heading">{t('historyBaseline')}</h3><p class="muted">{t('historyRule')}</p>{#if forecast.history.length}<ul>{#each forecast.history as item (item.accountId)}<li><span><strong>{item.accountName}</strong><small>{item.from} – {item.through} · {item.eligibleDays} {t('days')}</small><small>{t('historyTotals')}: {t('outflows')} {money(item.expenseTotal)} · {t('inflows')} {money(item.incomeTotal)}</small></span><strong>{t('dailyAverage')}<br>{t('outflows')} {money(item.dailyExpenseAverage)} · {t('inflows')} {money(item.dailyIncomeAverage)}</strong></li>{/each}</ul>{:else}<p>{t('historyUnavailable')}</p>{/if}<p class="muted">{t('historyNotIncluded')}</p>{#if historyTransactions.length}<h4>{t('baselineOverrides')}</h4><p class="muted">{t('baselineOverridesHint')}</p><ul>{#each historyTransactions as item (item.id)}<li><span><strong>{item.merchant||item.categoryName||item.type}</strong><small>{monthDay(String(item.date).slice(0,10))} · {item.categoryName??item.type}</small></span><span class="override-control"><strong>{money(item.amount)}</strong><Button variant="outline" size="sm" disabled={historyBusy===item.id} onclick={()=>toggleHistoryOverride(item)}>{item.excluded?t('includeInBaseline'):t('excludeFromBaseline')}</Button></span></li>{/each}</ul>{/if}</section>
      {#if uncertainReceivables.length}<section class="event-list" aria-labelledby="uncertain-invoices-heading"><h3 id="uncertain-invoices-heading">{t('uncertainReceivables')}</h3><p class="muted">{t('uncertainReceivablesHint')}</p><ul>{#each uncertainReceivables as invoice (invoice.invoiceId)}<li><span><strong>{invoice.invoiceNumber}</strong><small>{t('dueDate')}: {monthDay(invoice.dueDate)}</small><Button variant="link" size="sm" href={`/invoices/${invoice.invoiceId}`}>{t('reviewInvoice')}</Button></span><strong>{invoice.currency} {concealed(invoice.outstanding,privacy.hidden)}</strong></li>{/each}</ul></section>{/if}
      <p class="assumption">{t('assumptions')}</p>
    </Card.Content></Card.Root>
    <Card.Root><Card.Header><Card.Title>{t('attention')}</Card.Title><Card.Description>{t('suggestionIntro')}</Card.Description><Card.Description>{t('assistantDisclaimer')}</Card.Description></Card.Header><Card.Content>
      {#if suggestions.length}<div class="suggestions">{#each suggestions as item (item.id)}<article><strong class="suggestion-title"><span class:shortfall-icon={item.kind==='shortfall'} class:low-icon={item.kind==='low_balance'} aria-hidden="true">{item.kind==='shortfall'?'↘':item.kind==='low_balance'?'↓':item.kind==='invoice_followup'?'↗':'•'}</span>{actionLabel(item)}</strong><p>{item.facts?.date?`${t('projectedDate')}: ${monthDay(item.facts.date)}.`:''}{item.facts?.dueDate?`${t('dueDate')}: ${monthDay(item.facts.dueDate)}.`:''}{item.facts?.amount?` ${t('projectedAmount')}: ${money(item.facts.amount)}.`:''}{item.facts?.accountName?` ${t('account')}: ${item.facts.accountName}.`:''}{#if item.kind==='payment_delay'} {item.facts.billName} · {#if item.facts.needsTermsConfirmation}{t('checkTermsNotice')} {t('shortfallOn')} {monthDay(item.facts.shortfallDate)}{:else}{monthDay(item.facts.currentDate)} → {monthDay(item.facts.deferrableUntil)} · {item.facts.alternativeShortfallDate?`${t('shortfallOn')} ${monthDay(item.facts.alternativeShortfallDate)}`:t('shortfallAvoided')}{/if}{/if}</p><small>{t('why')}: {item.kind==='invoice_followup'?t('whyInvoice'):item.kind==='payment_delay'?(item.facts.needsTermsConfirmation?t('whyCheckTerms'):t('whyPaymentDelay')):t('whyShortfall')}</small>
        {#if item.kind==='savings'}<Button variant="outline" size="sm" href="/goals">{t('reviewGoal')}</Button>{#if !proposals[item.id]}<Button variant="outline" size="sm" onclick={()=>createProposal(item,'contribute_to_goal')} disabled={actionBusy===item.id}>{actionBusy===item.id?t('preparing'):t('prepareContribution')}</Button>{:else}<div class="proposal-preview"><strong>{t('reviewBeforeSend')}</strong><p>{proposals[item.id].payload.goalName}</p><p>{proposals[item.id].payload.currency} {concealed(proposals[item.id].payload.amount,privacy.hidden)}</p><p>{t('allocationOnly')}</p><Button size="sm" onclick={()=>confirmProposal(item)} disabled={actionBusy===item.id}>{actionBusy===item.id?t('saving'):t('confirmContribution')}</Button></div>{/if}{/if}{#if item.kind==='payment_delay'}<Button variant="outline" size="sm" href="/bills">{t('reviewBill')}</Button>{#if !item.facts.needsTermsConfirmation}{#if !proposals[item.id]}<Button variant="outline" size="sm" onclick={()=>createProposal(item,'review_payment_date')} disabled={actionBusy===item.id}>{actionBusy===item.id?t('preparing'):t('prepareDateChange')}</Button>{:else}<div class="proposal-preview"><strong>{t('reviewBeforeSend')}</strong><p>{proposals[item.id].payload.billName}</p><p>{t('currentDate')}: {monthDay(proposals[item.id].payload.currentExpectedDate)} → {monthDay(proposals[item.id].payload.proposedDate)}</p><p>{proposals[item.id].payload.alternativeShortfallDate?`${t('shortfallOn')} ${monthDay(proposals[item.id].payload.alternativeShortfallDate)}`:t('shortfallAvoided')}</p><p>{t('forecastDateOnly')}</p><Button size="sm" onclick={()=>confirmProposal(item)} disabled={actionBusy===item.id}>{actionBusy===item.id?t('saving'):t('confirmDateChange')}</Button></div>{/if}{/if}{/if}{#if item.kind==='invoice_followup'}<Button variant="outline" size="sm" href={`/invoices/${item.facts.invoiceId}`}>{t('reviewInvoice')}</Button>{#if !proposals[item.id]}<Button variant="outline" size="sm" onclick={()=>createProposal(item)} disabled={actionBusy===item.id}>{actionBusy===item.id?t('preparing'):t('prepareReminder')}</Button>{:else}<div class="proposal-preview"><strong>{t('reviewBeforeSend')}</strong><p>{t('to')}: {proposals[item.id].payload.recipient}</p><p>{t('invoice')} {proposals[item.id].payload.invoiceNumber} · {proposals[item.id].payload.currency} {concealed(proposals[item.id].payload.outstanding,privacy.hidden)}</p><p>{privacy.hidden?(ui.locale==='id'?'Detail keuangan disembunyikan.':'Financial details are hidden.'):proposals[item.id].payload.message}</p><Button size="sm" onclick={()=>confirmProposal(item)} disabled={actionBusy===item.id}>{actionBusy===item.id?t('sending'):t('confirmSend')}</Button></div>{/if}{/if}
        <div class="feedback"><Button variant="ghost" size="sm" onclick={()=>suggestionFeedback(item,'helpful')}>{t('helpful')}</Button><Button variant="ghost" size="sm" onclick={()=>suggestionFeedback(item,'not_helpful')}>{t('notHelpful')}</Button><Button variant="ghost" size="sm" onclick={()=>suggestionFeedback(item,'snooze')}>{t('snooze')}</Button><Button variant="ghost" size="sm" onclick={()=>suggestionFeedback(item,'dismiss')}>{t('dismiss')}</Button></div>
      </article>{/each}</div>{:else}<p class="muted">{t('noAlerts')}</p>{/if}
    </Card.Content></Card.Root>
  </div>
{/if}
<Card.Root id="privacy-settings" class="privacy"><Card.Header><Card.Title>{t('privacy')}</Card.Title><Card.Description>{t('privacyDescription')}</Card.Description></Card.Header><Card.Content>
  <div class="switches"><label><input type="checkbox" bind:checked={localForecast}/> {t('enableForecast')}</label><label><input type="checkbox" bind:checked={suggestionsEnabled}/> {t('enableSuggestions')}</label><label><input type="checkbox" bind:checked={categorization}/> {t('enableCategorization')}</label></div>
  <Field.FieldSet><Field.FieldLegend>{t('alertChannels')}</Field.FieldLegend><Field.FieldDescription>{t('alertChannelsDescription')}</Field.FieldDescription><div class="switches"><label><input type="checkbox" bind:checked={emailAlerts}/> {t('emailAlerts')}</label><label><input type="checkbox" bind:checked={pushAlerts}/> {t('pushAlerts')}</label><Button variant="outline" size="sm" onclick={saveChannels} disabled={savingChannels}>{savingChannels?t('saving'):t('saveChannels')}</Button></div></Field.FieldSet>
  <Field.FieldSet><Field.FieldLegend>{t('dataSources')}</Field.FieldLegend><Field.FieldDescription>{t('dataSourcesDescription')}</Field.FieldDescription><div class="source-grid">{#each Object.entries(labels) as [key,label]}<label><input type="checkbox" checked={permissions[key]??false} onchange={(event)=>permissions={...permissions,[key]:event.currentTarget.checked}}/>{label}</label>{/each}</div></Field.FieldSet>
  <Field.Field><Field.FieldLabel for="assistant-tone">{t('assistantTone')}</Field.FieldLabel><select id="assistant-tone" bind:value={tone}><option value="playful">{t('tonePlayful')}</option><option value="balanced">{t('toneBalanced')}</option><option value="professional">{t('toneProfessional')}</option></select><Field.FieldDescription>{t('toneDescription')}</Field.FieldDescription></Field.Field>
  <Field.FieldSet class="account-set"><Field.FieldLegend>{t('accountScope')}</Field.FieldLegend><Field.FieldDescription>{t('accountScopeDescription')}</Field.FieldDescription><div class="account-grid">{#each accountSettings as account (account.id)}<article><label class="include"><input type="checkbox" bind:checked={account.included}/><strong>{account.name}</strong><small>{account.currency} · {account.kind}</small></label><Field.Field><Field.FieldLabel for={`threshold-${account.id}`}>{t('lowThreshold')}</Field.FieldLabel><Input id={`threshold-${account.id}`}  type={privacy.hidden?'password':'text'} bind:value={account.lowBalanceThreshold} inputmode="decimal"/></Field.Field><Field.Field><Field.FieldLabel for={`reserve-${account.id}`}>{t('protectedAmount')}</Field.FieldLabel><Input id={`reserve-${account.id}`}  type={privacy.hidden?'password':'text'} bind:value={account.protectedAmount} inputmode="decimal"/></Field.Field></article>{/each}</div></Field.FieldSet>
  <div class="settings-row"><Field.Field><Field.FieldLabel for="safety-buffer">{t('extraBuffer')}</Field.FieldLabel><Input id="safety-buffer" bind:value={buffer} inputmode="decimal"/></Field.Field><Button onclick={save} disabled={saving||!settings}>{saving?t('saving'):t('save')}</Button></div>
  <p class="muted">{t('externalUnavailable')}</p>
  <div class="data-controls"><Button variant="outline" size="sm" onclick={exportAssistantData}>{t('exportAssistantData')}</Button><Button variant="outline" size="sm" onclick={deleteAssistantData} disabled={deletingData||!settings}>{deletingData?t('saving'):t('deleteAssistantData')}</Button></div>
</Card.Content></Card.Root>
<Card.Root class="rules-card"><Card.Header><div class="rule-heading"><div><Card.Title>{t('learnedRules')}</Card.Title><Card.Description>{t('learnedDescription')}</Card.Description></div><Button variant="outline" size="sm" onclick={resetLearnedRules} disabled={!rules.some((rule)=>rule.origin==='learned')}>{t('resetRules')}</Button></div></Card.Header><Card.Content>
  {#if rules.length}<div class="rule-list">{#each rules as rule (rule.id)}<article><span><strong>{rule.merchant}</strong><small>{rule.type} · {rule.categoryName} · {rule.supportCount} {t('examples')}, {rule.acceptedCount} {t('matching')}</small></span><Button variant="outline" size="sm" onclick={()=>setRuleEnabled(rule)}>{rule.enabled?t('disable'):t('enable')}</Button></article>{/each}</div>{:else}<p class="muted">{t('emptyRules')}</p>{/if}
</Card.Content></Card.Root>
<style>
:global(.money){font-size:clamp(20px,3vw,28px);font-variant-numeric:tabular-nums}.page-head{display:flex;justify-content:space-between;gap:18px;align-items:end;margin-bottom:22px}.head-controls{display:flex;align-items:end;gap:10px}.eyebrow{color:var(--muted-foreground);font-size:13px;margin:0 0 5px}h1{font:500 clamp(28px,4vw,38px) 'Fredoka Variable',sans-serif;margin:0}.page-head p:last-child{color:var(--muted-foreground);margin:8px 0 0;max-width:680px}.horizon{display:grid;gap:6px;min-width:150px;font-size:12px;color:var(--muted-foreground)}select{min-height:38px;border:1px solid var(--input);border-radius:var(--radius);background:var(--background);color:var(--foreground);padding:7px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.columns{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-top:14px}.chart-wrap{padding-top:8px}.cashflow-chart{width:100%;height:245px}.chart-dates{display:flex;justify-content:space-between;color:var(--muted-foreground);font-size:11px;margin-top:7px}.assumption,.muted{font-size:12px;line-height:1.6;color:var(--muted-foreground)}.flags{padding:12px;border:1px solid var(--border);border-radius:12px;background:var(--muted);font-size:13px}.flags p{margin:5px 0;text-transform:capitalize}.flags small{color:var(--muted-foreground)}.suggestions{display:grid;gap:10px}.suggestions article{padding:12px;border:1px solid var(--border);border-radius:12px}.suggestions p{font-size:13px;color:var(--muted-foreground);margin:5px 0}.suggestions small{font-size:11px;color:var(--muted-foreground)}:global(.privacy){margin-top:14px}.switches{display:flex;flex-wrap:wrap;gap:12px 24px;margin-bottom:20px}.switches label,.source-grid label{display:flex;align-items:center;gap:8px;font-size:13px}.source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:12px}:global(.rules-card){margin-top:14px}.rule-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.data-table{margin-top:14px}.event-list{margin-top:16px}.event-list h3{font-size:14px;margin:0 0 8px}.event-list h4{font-size:13px;margin:14px 0 4px}.event-list ul{list-style:none;padding:0;margin:0;max-height:260px;overflow:auto}.event-list li{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-top:1px solid var(--border);font-size:12px}.event-list li span{display:grid;gap:3px}.event-list li small{color:var(--muted-foreground)}.event-list li>strong{white-space:nowrap;font-variant-numeric:tabular-nums}.override-control{grid-template-columns:auto auto;align-items:center;justify-items:end}.data-table summary{cursor:pointer;color:var(--primary);font-size:13px;padding:8px 0}.table-scroll{max-height:380px;overflow:auto;border:1px solid var(--border);border-radius:10px}.data-table table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}.data-table caption{text-align:left;padding:10px;font-weight:600}.data-table th,.data-table td{text-align:right;padding:8px;border-top:1px solid var(--border);font-variant-numeric:tabular-nums}.data-table th:first-child,.data-table td:nth-child(2){text-align:left}.feedback{display:flex;flex-wrap:wrap;gap:3px;margin-top:8px}.proposal-preview{margin-top:10px;padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--muted)}.proposal-preview p{overflow-wrap:anywhere}.rule-list{display:grid;gap:8px}.rule-list article{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--border);padding:10px 0}.rule-list article>span{display:grid;gap:3px}.rule-list small{font-size:12px;color:var(--muted-foreground)}:global(.account-set){margin-top:18px}.account-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:12px}.account-grid article{display:grid;gap:10px;padding:12px;border:1px solid var(--border);border-radius:12px}.include{display:grid;grid-template-columns:auto 1fr;align-items:center;column-gap:8px}.include input{grid-row:span 2}.include small{grid-column:2;color:var(--muted-foreground);font-size:11px}.settings-row{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-top:20px}.settings-row :global(input){max-width:260px}.error{color:var(--destructive)}@media(max-width:760px){.rule-heading{align-items:flex-start;flex-direction:column}.page-head{align-items:stretch;flex-direction:column}.head-controls{align-items:stretch;flex-wrap:wrap}.horizon{max-width:160px}.stats{grid-template-columns:1fr}.columns{grid-template-columns:1fr}.settings-row{align-items:stretch;flex-direction:column}.settings-row :global(input){max-width:none}.source-grid,.account-grid{grid-template-columns:1fr}}
.horizon select{min-height:44px}
.switches label,.source-grid label,.include{min-height:44px}
.data-table summary{display:flex;align-items:center;min-height:44px}
:global(.head-controls button),:global(.suggestions button),:global(.feedback button),:global(.privacy button),:global(.rules-card button){min-height:44px}

.suggestion-title{display:flex;align-items:center;gap:7px}.suggestion-title span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--secondary);color:var(--secondary-foreground);font-size:16px}.suggestion-title span.shortfall-icon{color:var(--destructive)}.suggestion-title span.low-icon{color:var(--primary)}
.data-controls{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}.data-controls :global(button){min-height:44px}
.scenario-select{display:flex;align-items:center;gap:8px;margin-top:10px;color:var(--muted-foreground);font-size:12px}.scenario-select select{min-height:44px}
.chart-summary{margin:6px 0 0;color:var(--muted-foreground);font-size:12px;line-height:1.5}
/* Business cashflow is reviewed as an operating report, so keep its cards
   compact while retaining the warmer, roomier Personal workspace treatment. */
:global(.app-shell[data-mode='business'] .stats){gap:10px}
:global(.app-shell[data-mode='business'] .columns){gap:10px}
:global(.app-shell[data-mode='business'] .suggestions article){padding:10px;border-radius:8px}
:global(.app-shell[data-mode='business'] .event-list li){padding:6px 0}
</style>
